  getConcept: function(i) {
    var c = this.concepts[i];
    if (!c) return null;
    var nm = c[1];
    var vn = c[7];
    return {
      id: c[0],
      nm: nm,
      dg: c[2] || vn,
      st: c[3],
      fm: c[4],
      cm: c[5] ? [c[5]] : [],
      vt: c[6],
      vn: vn,
      vp: c[8],
      vpn: c[9] || nm,
      ap: c[10],
      apn: c[11],
      nti: Boolean(c[12]),
      cmm: Boolean(c[13])
    };
  },
  getGtin: function(gtin) {
    if (!gtin) return null;
    var str = String(gtin).trim();
    var row = this.gtinMap[str];
    if (!row && str.length < 14) {
      row = this.gtinMap[str.padStart(14, '0')];
    }
    if (!row && str.length === 14 && str.charAt(0) === '0') {
      row = this.gtinMap[str.substring(1)];
    }
    if (!row) return null;
    var c = (row[5] >= 0) ? this.getConcept(row[5]) : null;
    var pSuffix = (row[2] >= 0 && row[2] < this.packs.length) ? this.packs[row[2]] : '';
    var pDesc = c ? ((c.apn || c.nm) + (pSuffix ? ' ' + pSuffix : '')) : pSuffix;
    return {
      amppId: row[0],
      ampId: row[1],
      vmpId: c ? c.vp : '',
      packDesc: pDesc,
      isHist: Boolean(row[3]),
      isDisc: Boolean(row[4]),
      conceptIndex: row[5], 
      concept: c
    };
  }
